const proximoNumero = `-- name: ProximoNumero :one

INSERT INTO numeracoes (tipo, ano, ultimo) VALUES ($1::text, $2::int, 1)
ON CONFLICT (tipo, ano) DO UPDATE SET ultimo = numeracoes.ultimo + 1
RETURNING ultimo
`

type ProximoNumeroParams struct {
	Tipo string `json:"tipo"`
	Ano  int32  `json:"ano"`
}

// ---------------------------------------------------------------- Numeração (9.4)
// Próximo número do ano, de forma atômica.
func (q *Queries) ProximoNumero(ctx context.Context, arg ProximoNumeroParams) (int32, error) {
	row := q.db.QueryRow(ctx, proximoNumero, arg.Tipo, arg.Ano)
	var ultimo int32
	err := row.Scan(&ultimo)
	return ultimo, err
}

